    "CREATE TABLE agent_definitions (\n                    id TEXT PRIMARY KEY,\n                    name TEXT NOT NULL,\n                    description TEXT NOT NULL DEFAULT '',\n                    instructions TEXT NOT NULL DEFAULT '',\n                    tool_allowlist TEXT NOT NULL DEFAULT '[]',\n                    model TEXT NOT NULL DEFAULT '',\n                    -- v21 (ADR-147, TASK-32477): preset routing -- the\n                    -- provider this definition pins ('' = inherit the\n                    -- caller's provider at spawn) and its sampling-param\n                    -- overrides as a JSON object string ('{}' = none).\n                    provider TEXT NOT NULL DEFAULT '',\n                    params_json TEXT NOT NULL DEFAULT '{}',\n                    enabled INTEGER NOT NULL DEFAULT 1,\n                    max_wall_seconds REAL,\n                    deleted INTEGER NOT NULL DEFAULT 0,\n                    created_at TEXT NOT NULL,\n                    updated_at TEXT NOT NULL\n                , fallback_models_json TEXT NOT NULL DEFAULT '[]')",
    'CREATE TABLE agent_run_steps (\n                    run_id TEXT NOT NULL REFERENCES agent_runs(id) ON DELETE CASCADE,\n                    seq INTEGER NOT NULL,\n                    payload TEXT NOT NULL,\n                    created_at TEXT NOT NULL,\n                    PRIMARY KEY (run_id, seq)\n                )',
    "CREATE TABLE agent_runs (\n                    id TEXT PRIMARY KEY,\n                    conversation_id TEXT NOT NULL,\n                    parent_run_id TEXT,\n                    agent_kind TEXT NOT NULL,\n                    task TEXT,\n                    status TEXT NOT NULL,\n                    steps TEXT NOT NULL DEFAULT '[]',\n                    result TEXT,\n                    budget TEXT,\n                    created_at TEXT NOT NULL,\n                    updated_at TEXT NOT NULL,\n                    assistant_message_id TEXT,\n                    agent_definition TEXT,\n                    definition_fingerprint TEXT,\n                    wake_delivered_at TEXT,\n                    -- v11 (fleet PR3b Task 4, spec SS6): when this run is\n                    -- a CONTINUATION of a finished sub-agent -- a NEW run\n                    -- seeded from the old one's retained in-memory\n                    -- transcript via send_to_agent -- this records the\n                    -- run it resumed from. NULL for every ordinary run.\n                    -- Lineage only: parent_run_id still points at the\n                    -- RESUMING turn's primary, never at the old run.\n                    resumed_from_run_id TEXT,\n                    -- v14 (ADR-080): the stable parent Trace event that\n                    -- caused this run to exist. NULL for primary and\n                    -- legacy runs whose precise cause was not captured.\n                    spawn_event_id TEXT,\n                    budget_tokens INTEGER CHECK (\n                        budget_tokens IS NULL OR\n                        (typeof(budget_tokens) = 'integer' AND budget_tokens >= 0)\n                    ),\n                    -- v21 (ADR-147, TASK-32477; planned as v16, renumbered\n                    -- past dev's v16-v20 via #2641 and #2665): the\n                    -- resolved-target snapshot -- where this run's agent\n                    -- ACTUALLY went after preset routing resolved\n                    -- (provider, model, base_url, and the merged params as\n                    -- a raw JSON object string). Written once at spawn\n                    -- (Task 6); read back verbatim on resume/continuation\n                    -- (Task 8). NULL for every pre-v21 row and for runs\n                    -- spawned without routing resolution.\n                    resolved_provider TEXT,\n                    resolved_model TEXT,\n                    resolved_base_url TEXT,\n                    resolved_params_json TEXT\n                , work_chain_id TEXT REFERENCES automatic_work_chains(id), fallback_targets_json TEXT, active_fallback_index INTEGER NOT NULL DEFAULT 0)",
    "CREATE TABLE agent_worktrees (\n    run_id TEXT PRIMARY KEY REFERENCES agent_runs(id),\n    workspace_id TEXT NOT NULL,\n    binding_id TEXT NOT NULL,\n    locator_fingerprint TEXT NOT NULL,\n    repo_root TEXT NOT NULL,\n    repo_identity TEXT NOT NULL,\n    git_common_dir TEXT NOT NULL,\n    git_common_identity TEXT NOT NULL,\n    child_path TEXT NOT NULL,\n    child_identity TEXT NOT NULL,\n    branch TEXT NOT NULL,\n    base_sha TEXT NOT NULL,\n    execution_id TEXT NOT NULL,\n    writer_state TEXT NOT NULL DEFAULT 'held'\n        CHECK(writer_state IN ('held', 'drained', 'uncertain')),\n    mutation_state TEXT NOT NULL DEFAULT 'unresolved'\n        CHECK(mutation_state IN ('unresolved', 'applying', 'merging', 'discarding',\n            'applied', 'merged', 'discarded_cleanup_pending', 'uncertain')),\n    operation_id TEXT,\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL\n)",
    "CREATE TABLE automatic_chat_start_attempts (\n    id TEXT PRIMARY KEY,\n    source_run_id TEXT NOT NULL REFERENCES agent_runs(id),\n    source_chain_id TEXT NOT NULL REFERENCES automatic_work_chains(id),\n    chain_id TEXT NOT NULL UNIQUE REFERENCES automatic_work_chains(id),\n    conversation_id TEXT NOT NULL,\n    session_id TEXT NOT NULL,\n    session_incarnation TEXT NOT NULL,\n    owner_id TEXT NOT NULL,\n    draft_revision INTEGER NOT NULL CHECK (typeof(draft_revision)='integer' AND draft_revision>=0),\n    context_epoch INTEGER NOT NULL CHECK (typeof(context_epoch)='integer' AND context_epoch>=0),\n    request_fingerprint TEXT NOT NULL CHECK (length(request_fingerprint)=64 AND request_fingerprint NOT GLOB '*[^0-9a-f]*'),\n    generation_reservation_id TEXT NOT NULL UNIQUE REFERENCES automatic_work_reservations(id),\n    state TEXT NOT NULL CHECK (state IN ('prepared', 'accepted', 'completed', 'aborted', 'review_required')),\n    created_at REAL NOT NULL,\n    accepted_at REAL,\n    completed_at REAL\n)",
    'CREATE TABLE automatic_progress_wake_claims (\n    message_id TEXT PRIMARY KEY,\n    source_run_id TEXT NOT NULL REFERENCES agent_runs(id),\n    attempt_id TEXT NOT NULL REFERENCES automatic_wake_attempts(id)\n)',
    "CREATE TABLE automatic_wake_attempts (\n    id TEXT PRIMARY KEY,\n    chain_id TEXT NOT NULL REFERENCES automatic_work_chains(id),\n    conversation_id TEXT NOT NULL,\n    session_id TEXT NOT NULL,\n    owner_id TEXT NOT NULL,\n    generation_reservation_id TEXT NOT NULL UNIQUE REFERENCES automatic_work_reservations(id),\n    run_ids_json TEXT NOT NULL,\n    state TEXT NOT NULL CHECK (state IN ('prepared', 'accepted', 'completed', 'aborted', 'review_required')),\n    created_at REAL NOT NULL,\n    accepted_at REAL,\n    completed_at REAL\n, cause TEXT NOT NULL DEFAULT 'completion' CHECK (cause IN ('completion', 'progress', 'mixed')), message_ids_json TEXT NOT NULL DEFAULT '[]', attempt_kind TEXT NOT NULL DEFAULT 'fleet_wake' CHECK (attempt_kind IN ('fleet_wake', 'goal_iteration')))",
    'CREATE TABLE automatic_wake_claims (\n    run_id TEXT PRIMARY KEY REFERENCES agent_runs(id),\n    attempt_id TEXT NOT NULL REFERENCES automatic_wake_attempts(id)\n)',
    "CREATE TABLE automatic_work_chains (\n    id TEXT PRIMARY KEY,\n    conversation_id TEXT NOT NULL,\n    root_submission_id TEXT NOT NULL UNIQUE,\n    limits_json TEXT NOT NULL,\n    status TEXT NOT NULL DEFAULT 'active'\n        CHECK (status IN ('active', 'paused', 'review_required')),\n    pause_reason TEXT,\n    created_at REAL NOT NULL,\n    started_at REAL,\n    deadline_at REAL,\n    clock_owner_id TEXT,\n    started_monotonic REAL,\n    last_observed_at REAL NOT NULL\n, allowance_root_chain_id TEXT REFERENCES automatic_work_chains(id))",
    "CREATE TABLE automatic_work_reservations (\n    id TEXT PRIMARY KEY,\n    chain_id TEXT NOT NULL REFERENCES automatic_work_chains(id),\n    owner_id TEXT NOT NULL,\n    kind TEXT NOT NULL CHECK (kind IN ('generation', 'child_launch', 'model_call', 'tokens')),\n    amount INTEGER NOT NULL CHECK (typeof(amount) = 'integer' AND amount > 0),\n    state TEXT NOT NULL CHECK (state IN ('reserved', 'committed', 'released', 'settled', 'uncertain')),\n    actual_amount INTEGER CHECK (actual_amount IS NULL OR (typeof(actual_amount) = 'integer' AND actual_amount >= 0)),\n    created_at REAL NOT NULL,\n    updated_at REAL NOT NULL\n)",
    'CREATE TABLE automatic_work_runtime_owner (\n    singleton INTEGER PRIMARY KEY CHECK (singleton = 1),\n    owner_id TEXT NOT NULL CHECK (length(owner_id) BETWEEN 1 AND 256)\n)',
    'CREATE TABLE change_notes (\n                    id INTEGER PRIMARY KEY,\n                    run_id TEXT NOT NULL,\n                    root TEXT NOT NULL,\n                    path TEXT NOT NULL,\n                    hunk_index INTEGER NOT NULL,\n                    hunk_header TEXT NOT NULL,\n                    hunk_excerpt TEXT NOT NULL,\n                    note TEXT NOT NULL,\n                    created_at TEXT NOT NULL,\n                    delivered_at TEXT,\n                    -- v9 (TASK-16800 Task 6 fix round): which run\'s\n                    -- COMPLETION actually stamped this note delivered --\n                    -- distinct from `run_id` above, which anchors the note\n                    -- to the run whose DIFF it critiques. A note written\n                    -- against an earlier run\'s diff is commonly delivered\n                    -- on a LATER run\'s completion, so resume re-derivation\n                    -- needs this to place the disclosure row at the\n                    -- delivering run\'s position (matching live emission)\n                    -- instead of fragmenting/mis-anchoring at the\n                    -- annotated run. NULL until stamped, and NULL forever\n                    -- on rows stamped by code that predates this column.\n                    delivered_by_run_id TEXT,\n                    -- v10 (Qodo #6, PR #1779 fix round): the exact\n                    -- change_snapshots row (its own DB `id`) this note\'s\n                    -- hunk was read from. Two windows on the SAME run+\n                    -- root+path (a turn\'s own window and its surviving\n                    -- sub-agents\' post-turn window, PR3a-1 Task 6c) can\n                    -- theoretically carry the same hunk_header at the\n                    -- same hunk_index (identical position/line-count\n                    -- edits against different baselines produce\n                    -- byte-identical "@@ ... @@" headers, since a header\n                    -- encodes only positions/counts, never content) --\n                    -- (run_id, hunk_index, hunk_header) alone can\'t then\n                    -- say which window\'s diff was actually annotated.\n                    -- NULL for legacy rows saved before this column\n                    -- existed; the card falls back to hunk_index+\n                    -- hunk_header matching for those.\n                    snapshot_id INTEGER,\n                    -- v12 (TASK-18060 Task 1, review-rail spec §4): anchor\n                    -- kind + diff-line anchoring, for the Review screen\'s\n                    -- plannotator-style comments alongside the card\'s\n                    -- existing hunk notes. \'hunk\' is every pre-v11 row\'s\n                    -- true, honest kind (nothing else existed before this\n                    -- column), so the DEFAULT both back-declares existing\n                    -- rows correctly and keeps every V1.5 caller (which\n                    -- never passes anchor_kind) byte-compatible.\n                    -- diff_line_index is 0-based over the file\'s FULL diff\n                    -- text (same semantics as hunk_index, a distinct\n                    -- axis), NULL except for \'diff_line\' rows.\n                    -- diff_line_text is the anchored line, captured\n                    -- verbatim at note-creation time -- same retention\n                    -- posture as hunk_excerpt (self-contained even after\n                    -- shadow-repo snapshot pruning), NULL except for\n                    -- \'diff_line\' rows. For \'diff_line\' rows the hunk\n                    -- fields ABOVE are ALSO populated (the hunk the line\n                    -- falls in) -- a deliberate convergence so the card\'s\n                    -- existing hunk-note filter renders line comments\n                    -- under their hunk with no card changes. For \'file\'\n                    -- rows (whole-file comments) hunk_index=-1,\n                    -- hunk_header=\'\', hunk_excerpt=\'\' -- sentinels that\n                    -- can never match a real hunk, keeping them out of\n                    -- the card\'s hunk-note filter.\n                    anchor_kind TEXT NOT NULL DEFAULT \'hunk\',\n                    diff_line_index INTEGER,\n                    diff_line_text TEXT\n                )',
    "CREATE TABLE change_snapshots (\n                    id INTEGER PRIMARY KEY AUTOINCREMENT,\n                    run_id TEXT NOT NULL,\n                    root TEXT NOT NULL,\n                    baseline_sha TEXT NOT NULL,\n                    end_sha TEXT NOT NULL,\n                    files_changed INTEGER NOT NULL DEFAULT 0,\n                    adds INTEGER NOT NULL DEFAULT 0,\n                    dels INTEGER NOT NULL DEFAULT 0,\n                    reverted TEXT NOT NULL DEFAULT '',\n                    tracking_error TEXT NOT NULL DEFAULT '',\n                    untracked_oversize INTEGER NOT NULL DEFAULT 0,\n                    nested_repos TEXT NOT NULL DEFAULT '[]',\n                    -- v5->v6 (PR3a-1 Task 6c): which WINDOW this row\n                    -- covers. 'turn' is the turn's own B/E window;\n                    -- 'turn_concurrent_subagent' is the same window taken\n                    -- while a sub-agent from an EARLIER turn was writing\n                    -- (so the diff may include changes this turn's agent\n                    -- did not make -- disclosed, never implied);\n                    -- 'subagent_post_turn' is the window AFTER a turn's E\n                    -- during which its surviving sub-agents were still\n                    -- working. The default keeps every pre-existing row\n                    -- reading as what it was.\n                    kind TEXT NOT NULL DEFAULT 'turn',\n                    created_at TEXT NOT NULL\n                )",
    "CREATE TABLE console_activity_receipts (\n                activity_id TEXT PRIMARY KEY,\n                origin TEXT NOT NULL\n                    CHECK(origin IN ('ordinary', 'fleet_survivor')),\n                logical_outcome_id TEXT NOT NULL,\n                transition_revision INTEGER NOT NULL\n                    CHECK(transition_revision > 0),\n                session_id TEXT,\n                conversation_id TEXT,\n                run_id TEXT,\n                assistant_message_id TEXT,\n                status TEXT NOT NULL CHECK(status IN\n                    ('done', 'failed', 'stuck', 'stopped', 'cancelled')),\n                created_at TEXT NOT NULL,\n                acknowledged_at TEXT,\n                superseded_at TEXT,\n                CHECK(session_id IS NOT NULL OR conversation_id IS NOT NULL),\n                UNIQUE(origin, logical_outcome_id, transition_revision)\n            )",
    'CREATE TABLE goal_checkpoints (\n    attempt_id TEXT PRIMARY KEY REFERENCES automatic_wake_attempts(id),\n    goal_id TEXT NOT NULL REFERENCES goal_runs(id),\n    payload_hash TEXT NOT NULL,\n    payload_json TEXT NOT NULL CHECK(length(CAST(payload_json AS BLOB)) <= 131072)\n)',
    'CREATE TABLE goal_evidence (\n    id TEXT PRIMARY KEY,\n    goal_id TEXT NOT NULL REFERENCES goal_runs(id),\n    attempt_id TEXT NOT NULL REFERENCES automatic_wake_attempts(id),\n    payload_json TEXT NOT NULL CHECK(length(CAST(payload_json AS BLOB)) <= 131072)\n)',
    "CREATE TABLE goal_iterations (\n    id TEXT PRIMARY KEY,\n    goal_id TEXT NOT NULL REFERENCES goal_runs(id),\n    ordinal INTEGER NOT NULL CHECK (ordinal > 0),\n    launch_id TEXT NOT NULL UNIQUE,\n    attempt_id TEXT NOT NULL UNIQUE REFERENCES automatic_wake_attempts(id),\n    run_id TEXT REFERENCES agent_runs(id),\n    status TEXT NOT NULL,\n    revision INTEGER NOT NULL DEFAULT 1 CHECK (revision > 0),\n    check_results_json TEXT NOT NULL DEFAULT '[]' CHECK (length(CAST(check_results_json AS BLOB)) <= 131072),\n    evidence_refs_json TEXT NOT NULL DEFAULT '[]' CHECK (length(CAST(evidence_refs_json AS BLOB)) <= 8192),\n    UNIQUE(goal_id, ordinal)\n)",
    'CREATE TABLE goal_payload_reservations (\n    attempt_id TEXT PRIMARY KEY REFERENCES automatic_wake_attempts(id),\n    goal_id TEXT NOT NULL REFERENCES goal_runs(id),\n    bytes INTEGER NOT NULL CHECK(bytes >= 0)\n)',
    'CREATE TABLE goal_reports (\n    id TEXT PRIMARY KEY,\n    goal_id TEXT NOT NULL REFERENCES goal_runs(id),\n    iteration_id TEXT UNIQUE REFERENCES goal_iterations(id),\n    payload_json TEXT NOT NULL CHECK (length(CAST(payload_json AS BLOB)) <= 65536)\n)',
    "CREATE TABLE goal_runs (\n    id TEXT PRIMARY KEY,\n    launch_id TEXT NOT NULL UNIQUE,\n    payload_hash TEXT NOT NULL,\n    request_json TEXT NOT NULL CHECK (length(CAST(request_json AS BLOB)) <= 131072),\n    conversation_id TEXT NOT NULL UNIQUE,\n    chain_id TEXT NOT NULL UNIQUE REFERENCES automatic_work_chains(id),\n    revision INTEGER NOT NULL DEFAULT 1 CHECK (revision > 0),\n    status TEXT NOT NULL DEFAULT 'starting',\n    pause_reason TEXT,\n    created_at REAL NOT NULL,\n    updated_at REAL NOT NULL\n)",
    'CREATE TABLE goal_waits (\n    goal_id TEXT PRIMARY KEY REFERENCES goal_runs(id),\n    retry_at REAL NOT NULL,\n    reason TEXT NOT NULL\n)',
    'CREATE TABLE schema_version (\n                    version INTEGER PRIMARY KEY NOT NULL\n                )',
    'CREATE TABLE sqlite_sequence(name,seq)',
    'CREATE TABLE workflow_active_intervals (\n    id TEXT PRIMARY KEY,\n    workflow_id TEXT NOT NULL REFERENCES workflow_runs(id),\n    owner_id TEXT NOT NULL,\n    started_at REAL NOT NULL CHECK(started_at>=0),\n    ended_at REAL CHECK(ended_at>=started_at),\n    charged_seconds REAL NOT NULL DEFAULT 0 CHECK(charged_seconds>=0)\n)',
    'CREATE TABLE workflow_decisions (\n    id TEXT PRIMARY KEY,\n    workflow_id TEXT NOT NULL,\n    plan_revision INTEGER NOT NULL,\n    phase_id TEXT NOT NULL,\n    control_revision INTEGER NOT NULL CHECK(control_revision>0),\n    payload_json TEXT NOT NULL CHECK(length(CAST(payload_json AS BLOB)) <= 131072),\n    UNIQUE(workflow_id, control_revision),\n    FOREIGN KEY(workflow_id, plan_revision, phase_id) REFERENCES workflow_phases(workflow_id, plan_revision, phase_id)\n)',
    "CREATE TABLE workflow_payload_reservations (\n    attempt_id TEXT PRIMARY KEY,\n    workflow_id TEXT NOT NULL,\n    bytes INTEGER NOT NULL CHECK(typeof(bytes)='integer' AND bytes BETWEEN 1 AND 131072),\n    state TEXT NOT NULL CHECK(state IN ('reserved','published','removed')),\n    FOREIGN KEY(attempt_id, workflow_id) REFERENCES workflow_task_attempts(id, workflow_id)\n)",
    "CREATE TABLE workflow_phase_attempts (\n    id TEXT PRIMARY KEY,\n    workflow_id TEXT NOT NULL,\n    plan_revision INTEGER NOT NULL,\n    phase_id TEXT NOT NULL,\n    ordinal INTEGER NOT NULL CHECK(typeof(ordinal)='integer' AND ordinal>0),\n    native_attempt_id TEXT UNIQUE REFERENCES automatic_wake_attempts(id),\n    status TEXT NOT NULL CHECK(status IN ('prepared','accepted','completed','failed','uncertain','closed')),\n    retirement TEXT NOT NULL DEFAULT 'pending' CHECK(retirement IN ('pending','drained','unknown')),\n    UNIQUE(workflow_id, plan_revision, phase_id, ordinal),\n    FOREIGN KEY(workflow_id, plan_revision, phase_id) REFERENCES workflow_phases(workflow_id, plan_revision, phase_id)\n)",
    'CREATE TABLE workflow_phases (\n    workflow_id TEXT NOT NULL,\n    plan_revision INTEGER NOT NULL,\n    phase_id TEXT NOT NULL,\n    ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 1 AND 6),\n    PRIMARY KEY(workflow_id, plan_revision, phase_id),\n    UNIQUE(workflow_id, plan_revision, ordinal),\n    FOREIGN KEY(workflow_id, plan_revision) REFERENCES workflow_plan_revisions(workflow_id, revision)\n)',
    "CREATE TABLE workflow_plan_revisions (\n    workflow_id TEXT NOT NULL REFERENCES workflow_runs(id),\n    revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>0),\n    payload_hash TEXT NOT NULL,\n    payload_json TEXT NOT NULL CHECK(length(CAST(payload_json AS BLOB)) <= 131072),\n    PRIMARY KEY(workflow_id, revision)\n)",
    'CREATE TABLE workflow_results (\n    attempt_id TEXT PRIMARY KEY REFERENCES workflow_payload_reservations(attempt_id),\n    workflow_id TEXT NOT NULL,\n    payload_hash TEXT NOT NULL,\n    payload_json TEXT NOT NULL CHECK(length(CAST(payload_json AS BLOB)) <= 131072),\n    FOREIGN KEY(attempt_id, workflow_id) REFERENCES workflow_task_attempts(id, workflow_id)\n)',
    "CREATE TABLE workflow_runs (\n    id TEXT PRIMARY KEY,\n    launch_id TEXT NOT NULL UNIQUE,\n    payload_hash TEXT NOT NULL,\n    request_json TEXT NOT NULL CHECK(length(CAST(request_json AS BLOB)) <= 131072),\n    conversation_id TEXT NOT NULL,\n    chain_id TEXT NOT NULL UNIQUE REFERENCES automatic_work_chains(id),\n    control_revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(control_revision)='integer' AND control_revision>0),\n    progress_cursor INTEGER NOT NULL DEFAULT 0 CHECK(typeof(progress_cursor)='integer' AND progress_cursor>=0),\n    status TEXT NOT NULL DEFAULT 'awaiting_plan' CHECK(status IN ('awaiting_plan','awaiting_approval','running','paused','stopped','completed','closed','recovery_required','removed','awaiting_resume')),\n    created_at REAL NOT NULL,\n    updated_at REAL NOT NULL\n)",
    "CREATE TABLE workflow_task_attempts (\n    id TEXT PRIMARY KEY,\n    workflow_id TEXT NOT NULL,\n    plan_revision INTEGER NOT NULL,\n    phase_id TEXT NOT NULL,\n    task_id TEXT NOT NULL,\n    ordinal INTEGER NOT NULL CHECK(typeof(ordinal)='integer' AND ordinal>0),\n    run_id TEXT UNIQUE REFERENCES agent_runs(id),\n    native_attempt_id TEXT UNIQUE REFERENCES automatic_wake_attempts(id),\n    status TEXT NOT NULL CHECK(status IN ('prepared','accepted','completed','failed','uncertain','closed')),\n    retirement TEXT NOT NULL DEFAULT 'pending' CHECK(retirement IN ('pending','drained','unknown')),\n    UNIQUE(id, workflow_id),\n    UNIQUE(workflow_id, plan_revision, task_id, ordinal),\n    FOREIGN KEY(workflow_id, plan_revision, phase_id, task_id) REFERENCES workflow_tasks(workflow_id, plan_revision, phase_id, task_id)\n)",
    'CREATE TABLE workflow_tasks (\n    workflow_id TEXT NOT NULL,\n    plan_revision INTEGER NOT NULL,\n    phase_id TEXT NOT NULL,\n    task_id TEXT NOT NULL,\n    ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 1 AND 12),\n    PRIMARY KEY(workflow_id, plan_revision, phase_id, task_id),\n    UNIQUE(workflow_id, plan_revision, task_id),\n    FOREIGN KEY(workflow_id, plan_revision, phase_id) REFERENCES workflow_phases(workflow_id, plan_revision, phase_id)\n)',
    "CREATE TRIGGER automatic_chain_identity_immutable\nBEFORE UPDATE OF id, conversation_id, root_submission_id, limits_json, allowance_root_chain_id ON automatic_work_chains\nWHEN OLD.id IS NOT NEW.id\n  OR OLD.allowance_root_chain_id IS NOT NEW.allowance_root_chain_id\n  OR OLD.conversation_id IS NOT NEW.conversation_id\n  OR OLD.root_submission_id IS NOT NEW.root_submission_id\n  OR OLD.limits_json IS NOT NEW.limits_json\nBEGIN SELECT RAISE(ABORT, 'automatic chain identity is immutable'); END",
    "CREATE TRIGGER automatic_chain_root_insert\nBEFORE INSERT ON automatic_work_chains\nWHEN NEW.allowance_root_chain_id IS NOT NULL\nAND (NEW.id=NEW.allowance_root_chain_id OR NOT EXISTS (\n    SELECT 1 FROM automatic_work_chains WHERE id=NEW.allowance_root_chain_id\n    AND allowance_root_chain_id IS NULL))\nBEGIN SELECT RAISE(ABORT, 'automatic allowance must name a direct root'); END",
    "CREATE TRIGGER automatic_chain_root_update\nBEFORE UPDATE OF allowance_root_chain_id ON automatic_work_chains\nWHEN NEW.allowance_root_chain_id IS NOT NULL\nAND (NEW.id=NEW.allowance_root_chain_id OR NOT EXISTS (\n    SELECT 1 FROM automatic_work_chains WHERE id=NEW.allowance_root_chain_id\n    AND allowance_root_chain_id IS NULL))\nBEGIN SELECT RAISE(ABORT, 'automatic allowance must name a direct root'); END",
    "CREATE TRIGGER automatic_chat_start_identity_immutable\nBEFORE UPDATE OF id, source_run_id, source_chain_id, chain_id, conversation_id,\n    session_id, session_incarnation, owner_id, draft_revision, context_epoch,\n    request_fingerprint, generation_reservation_id ON automatic_chat_start_attempts\nWHEN OLD.id IS NOT NEW.id OR OLD.source_run_id IS NOT NEW.source_run_id\n  OR OLD.source_chain_id IS NOT NEW.source_chain_id OR OLD.chain_id IS NOT NEW.chain_id\n  OR OLD.conversation_id IS NOT NEW.conversation_id OR OLD.session_id IS NOT NEW.session_id\n  OR OLD.session_incarnation IS NOT NEW.session_incarnation OR OLD.owner_id IS NOT NEW.owner_id\n  OR OLD.draft_revision IS NOT NEW.draft_revision OR OLD.context_epoch IS NOT NEW.context_epoch\n  OR OLD.request_fingerprint IS NOT NEW.request_fingerprint\n  OR OLD.generation_reservation_id IS NOT NEW.generation_reservation_id\nBEGIN SELECT RAISE(ABORT, 'chat start identity is immutable'); END",
    "CREATE TRIGGER automatic_run_chain_immutable\nBEFORE UPDATE OF work_chain_id ON agent_runs\nWHEN OLD.work_chain_id IS NOT NULL AND OLD.work_chain_id IS NOT NEW.work_chain_id\nBEGIN SELECT RAISE(ABORT, 'run chain is immutable'); END",
    "CREATE TRIGGER automatic_run_chain_scope_insert\nBEFORE INSERT ON agent_runs WHEN NEW.work_chain_id IS NOT NULL\nAND NOT EXISTS (SELECT 1 FROM automatic_work_chains WHERE id=NEW.work_chain_id\n                AND conversation_id=NEW.conversation_id)\nBEGIN SELECT RAISE(ABORT, 'run chain scope mismatch'); END",
    "CREATE TRIGGER automatic_run_chain_scope_update\nBEFORE UPDATE OF work_chain_id, conversation_id ON agent_runs\nWHEN NEW.work_chain_id IS NOT NULL\nAND NOT EXISTS (SELECT 1 FROM automatic_work_chains WHERE id=NEW.work_chain_id\n                AND conversation_id=NEW.conversation_id)\nBEGIN SELECT RAISE(ABORT, 'run chain scope mismatch'); END",
    "CREATE TRIGGER goal_launch_immutable\nBEFORE UPDATE OF launch_id, payload_hash, request_json, conversation_id, chain_id ON goal_runs\nWHEN OLD.launch_id IS NOT NEW.launch_id OR OLD.payload_hash IS NOT NEW.payload_hash\n OR (OLD.request_json IS NOT NEW.request_json AND NOT (NEW.request_json='' AND NEW.status='removed'\n     AND OLD.status IN ('completed','paused','awaiting_result_review','stopped')\n     AND NOT EXISTS (SELECT 1 FROM goal_iterations i JOIN automatic_wake_attempts a ON a.id=i.attempt_id\n         WHERE i.goal_id=OLD.id AND a.state IN ('prepared','accepted','review_required'))))\n OR OLD.conversation_id IS NOT NEW.conversation_id OR OLD.chain_id IS NOT NEW.chain_id\nBEGIN SELECT RAISE(ABORT, 'goal launch is immutable'); END",
    "CREATE TRIGGER workflow_decision_immutable\nBEFORE UPDATE ON workflow_decisions\nBEGIN SELECT RAISE(ABORT, 'workflow decision is immutable'); END",
    "CREATE TRIGGER workflow_launch_immutable\nBEFORE UPDATE OF id, launch_id, payload_hash, request_json, conversation_id, chain_id ON workflow_runs\nBEGIN SELECT RAISE(ABORT, 'workflow launch is immutable'); END",
    "CREATE TRIGGER workflow_plan_immutable\nBEFORE UPDATE ON workflow_plan_revisions\nBEGIN SELECT RAISE(ABORT, 'workflow plan is immutable'); END",
    "CREATE TRIGGER workflow_result_immutable\nBEFORE UPDATE ON workflow_results\nBEGIN SELECT RAISE(ABORT, 'workflow result is immutable'); END",
    "CREATE TABLE agent_definitions (\n                    id TEXT PRIMARY KEY,\n                    name TEXT NOT NULL,\n                    description TEXT NOT NULL DEFAULT '',\n                    instructions TEXT NOT NULL DEFAULT '',\n                    tool_allowlist TEXT NOT NULL DEFAULT '[]',\n                    model TEXT NOT NULL DEFAULT '',\n                    enabled INTEGER NOT NULL DEFAULT 1,\n                    deleted INTEGER NOT NULL DEFAULT 0,\n                    created_at TEXT NOT NULL,\n                    updated_at TEXT NOT NULL\n                , max_wall_seconds REAL, provider TEXT NOT NULL DEFAULT '', params_json TEXT NOT NULL DEFAULT '{}', fallback_models_json TEXT NOT NULL DEFAULT '[]')",
    "CREATE TABLE agent_runs (\n                    id TEXT PRIMARY KEY,\n                    conversation_id TEXT NOT NULL,\n                    parent_run_id TEXT,\n                    agent_kind TEXT NOT NULL,\n                    task TEXT,\n                    status TEXT NOT NULL,\n                    steps TEXT NOT NULL DEFAULT '[]',\n                    result TEXT,\n                    budget TEXT,\n                    created_at TEXT NOT NULL,\n                    updated_at TEXT NOT NULL,\n                    assistant_message_id TEXT,\n                    agent_definition TEXT,\n                    definition_fingerprint TEXT,\n                    wake_delivered_at TEXT,\n                    -- v11 (fleet PR3b Task 4, spec SS6): when this run is\n                    -- a CONTINUATION of a finished sub-agent -- a NEW run\n                    -- seeded from the old one's retained in-memory\n                    -- transcript via send_to_agent -- this records the\n                    -- run it resumed from. NULL for every ordinary run.\n                    -- Lineage only: parent_run_id still points at the\n                    -- RESUMING turn's primary, never at the old run.\n                    resumed_from_run_id TEXT,\n                    -- v14 (ADR-080): the stable parent Trace event that\n                    -- caused this run to exist. NULL for primary and\n                    -- legacy runs whose precise cause was not captured.\n                    spawn_event_id TEXT,\n                    budget_tokens INTEGER CHECK (\n                        budget_tokens IS NULL OR\n                        (typeof(budget_tokens) = 'integer' AND budget_tokens >= 0)\n                    )\n                , work_chain_id TEXT REFERENCES automatic_work_chains(id), resolved_provider TEXT, resolved_model TEXT, resolved_base_url TEXT, resolved_params_json TEXT, fallback_targets_json TEXT, active_fallback_index INTEGER NOT NULL DEFAULT 0)",
    "CREATE TABLE agent_definitions (\n                    id TEXT PRIMARY KEY,\n                    name TEXT NOT NULL,\n                    description TEXT NOT NULL DEFAULT '',\n                    instructions TEXT NOT NULL DEFAULT '',\n                    tool_allowlist TEXT NOT NULL DEFAULT '[]',\n                    model TEXT NOT NULL DEFAULT '',\n                    enabled INTEGER NOT NULL DEFAULT 1,\n                    max_wall_seconds REAL,\n                    deleted INTEGER NOT NULL DEFAULT 0,\n                    created_at TEXT NOT NULL,\n                    updated_at TEXT NOT NULL\n                , provider TEXT NOT NULL DEFAULT '', params_json TEXT NOT NULL DEFAULT '{}', fallback_models_json TEXT NOT NULL DEFAULT '[]')",
    "CREATE TABLE automatic_work_chains (\n    id TEXT PRIMARY KEY,\n    conversation_id TEXT NOT NULL,\n    root_submission_id TEXT NOT NULL UNIQUE,\n    limits_json TEXT NOT NULL,\n    status TEXT NOT NULL DEFAULT 'active'\n        CHECK (status IN ('active', 'paused', 'review_required')),\n    pause_reason TEXT,\n    created_at REAL NOT NULL,\n    started_at REAL,\n    deadline_at REAL,\n    clock_owner_id TEXT,\n    started_monotonic REAL,\n    last_observed_at REAL NOT NULL,\n    allowance_root_chain_id TEXT REFERENCES automatic_work_chains(id)\n)",
    "CREATE TABLE agent_definitions (\n                    id TEXT PRIMARY KEY,\n                    name TEXT NOT NULL,\n                    description TEXT NOT NULL DEFAULT '',\n                    instructions TEXT NOT NULL DEFAULT '',\n                    tool_allowlist TEXT NOT NULL DEFAULT '[]',\n                    model TEXT NOT NULL DEFAULT '',\n                    -- v21 (ADR-147, TASK-32477): preset routing -- the\n                    -- provider this definition pins ('' = inherit the\n                    -- caller's provider at spawn) and its sampling-param\n                    -- overrides as a JSON object string ('{}' = none).\n                    provider TEXT NOT NULL DEFAULT '',\n                    params_json TEXT NOT NULL DEFAULT '{}',\n                    fallback_models_json TEXT NOT NULL DEFAULT '[]',\n                    enabled INTEGER NOT NULL DEFAULT 1,\n                    max_wall_seconds REAL,\n                    deleted INTEGER NOT NULL DEFAULT 0,\n                    created_at TEXT NOT NULL,\n                    updated_at TEXT NOT NULL\n                )",
    "CREATE TABLE agent_runs (\n                    id TEXT PRIMARY KEY,\n                    conversation_id TEXT NOT NULL,\n                    parent_run_id TEXT,\n                    agent_kind TEXT NOT NULL,\n                    task TEXT,\n                    status TEXT NOT NULL,\n                    steps TEXT NOT NULL DEFAULT '[]',\n                    result TEXT,\n                    budget TEXT,\n                    created_at TEXT NOT NULL,\n                    updated_at TEXT NOT NULL,\n                    assistant_message_id TEXT,\n                    agent_definition TEXT,\n                    definition_fingerprint TEXT,\n                    wake_delivered_at TEXT,\n                    -- v11 (fleet PR3b Task 4, spec SS6): when this run is\n                    -- a CONTINUATION of a finished sub-agent -- a NEW run\n                    -- seeded from the old one's retained in-memory\n                    -- transcript via send_to_agent -- this records the\n                    -- run it resumed from. NULL for every ordinary run.\n                    -- Lineage only: parent_run_id still points at the\n                    -- RESUMING turn's primary, never at the old run.\n                    resumed_from_run_id TEXT,\n                    -- v14 (ADR-080): the stable parent Trace event that\n                    -- caused this run to exist. NULL for primary and\n                    -- legacy runs whose precise cause was not captured.\n                    spawn_event_id TEXT,\n                    budget_tokens INTEGER CHECK (\n                        budget_tokens IS NULL OR\n                        (typeof(budget_tokens) = 'integer' AND budget_tokens >= 0)\n                    ),\n                    -- v21 (ADR-147, TASK-32477; planned as v16, renumbered\n                    -- past dev's v16-v20 via #2641 and #2665): the\n                    -- resolved-target snapshot -- where this run's agent\n                    -- ACTUALLY went after preset routing resolved\n                    -- (provider, model, base_url, and the merged params as\n                    -- a raw JSON object string). Written once at spawn\n                    -- (Task 6); read back verbatim on resume/continuation\n                    -- (Task 8). NULL for every pre-v21 row and for runs\n                    -- spawned without routing resolution.\n                    resolved_provider TEXT,\n                    resolved_model TEXT,\n                    resolved_base_url TEXT,\n                    resolved_params_json TEXT,\n                    fallback_targets_json TEXT,\n                    active_fallback_index INTEGER NOT NULL DEFAULT 0\n                , work_chain_id TEXT REFERENCES automatic_work_chains(id))",
    "CREATE TABLE automatic_wake_attempts (\n    id TEXT PRIMARY KEY,\n    chain_id TEXT NOT NULL REFERENCES automatic_work_chains(id),\n    conversation_id TEXT NOT NULL,\n    session_id TEXT NOT NULL,\n    owner_id TEXT NOT NULL,\n    generation_reservation_id TEXT NOT NULL UNIQUE REFERENCES automatic_work_reservations(id),\n    run_ids_json TEXT NOT NULL,\n    cause TEXT NOT NULL DEFAULT 'completion' CHECK (cause IN ('completion', 'progress', 'mixed')),\n    message_ids_json TEXT NOT NULL DEFAULT '[]',\n    state TEXT NOT NULL CHECK (state IN ('prepared', 'accepted', 'completed', 'aborted', 'review_required')),\n    created_at REAL NOT NULL,\n    accepted_at REAL,\n    completed_at REAL\n, attempt_kind TEXT NOT NULL DEFAULT 'fleet_wake' CHECK (attempt_kind IN ('fleet_wake', 'goal_iteration')))",
    'CREATE UNIQUE INDEX idx_workflow_open_interval ON workflow_active_intervals(workflow_id) WHERE ended_at IS NULL',
    'CREATE INDEX idx_workflow_task_phase ON workflow_task_claims(phase_attempt_id)',
    "CREATE TABLE automatic_wake_attempts (\n    id TEXT PRIMARY KEY,\n    chain_id TEXT NOT NULL REFERENCES automatic_work_chains(id),\n    conversation_id TEXT NOT NULL,\n    session_id TEXT NOT NULL,\n    owner_id TEXT NOT NULL,\n    generation_reservation_id TEXT NOT NULL UNIQUE REFERENCES automatic_work_reservations(id),\n    run_ids_json TEXT NOT NULL,\n    state TEXT NOT NULL CHECK (state IN ('prepared', 'accepted', 'completed', 'aborted', 'review_required')),\n    created_at REAL NOT NULL,\n    accepted_at REAL,\n    completed_at REAL\n, cause TEXT NOT NULL DEFAULT 'completion' CHECK (cause IN ('completion', 'progress', 'mixed')), message_ids_json TEXT NOT NULL DEFAULT '[]', attempt_kind TEXT NOT NULL DEFAULT 'fleet_wake' CHECK (attempt_kind IN ('fleet_wake', 'goal_iteration', 'workflow_phase')))",
    'CREATE TABLE workflow_active_intervals (\n    id TEXT PRIMARY KEY,\n    workflow_id TEXT NOT NULL REFERENCES workflow_runs(id),\n    owner_id TEXT NOT NULL,\n    started_at REAL NOT NULL CHECK(started_at>=0),\n    ended_at REAL CHECK(ended_at>=started_at),\n    charged_seconds REAL NOT NULL DEFAULT 0 CHECK(charged_seconds>=0)\n, clock_owner_id TEXT, started_monotonic REAL, observed_monotonic REAL)',
    "CREATE TABLE workflow_phase_attempts (\n    id TEXT PRIMARY KEY,\n    workflow_id TEXT NOT NULL REFERENCES workflow_runs(id),\n    plan_revision INTEGER,\n    phase_id TEXT,\n    ordinal INTEGER NOT NULL CHECK(typeof(ordinal)='integer' AND ordinal>0),\n    native_attempt_id TEXT UNIQUE REFERENCES automatic_wake_attempts(id),\n    status TEXT NOT NULL CHECK(status IN ('prepared','accepted','completed','failed','uncertain','closed')),\n    retirement TEXT NOT NULL DEFAULT 'pending' CHECK(retirement IN ('pending','drained','unknown')),\n    purpose TEXT NOT NULL DEFAULT 'execution' CHECK(purpose IN ('planning','execution')),\n    command_id TEXT UNIQUE,\n    control_revision INTEGER CHECK(control_revision>0),\n    result_bytes INTEGER NOT NULL DEFAULT 0 CHECK(result_bytes BETWEEN 0 AND 131072),\n    CHECK((purpose='execution' AND plan_revision IS NOT NULL AND phase_id IS NOT NULL)\n       OR (purpose='planning' AND phase_id IS NULL)),\n    UNIQUE(workflow_id, plan_revision, phase_id, ordinal),\n    FOREIGN KEY(workflow_id, plan_revision, phase_id) REFERENCES workflow_phases(workflow_id, plan_revision, phase_id)\n)",
    'CREATE TABLE workflow_task_claims (\n    task_attempt_id TEXT PRIMARY KEY REFERENCES workflow_task_attempts(id),\n    phase_attempt_id TEXT NOT NULL REFERENCES workflow_phase_attempts(id),\n    child_reservation_id TEXT UNIQUE REFERENCES automatic_work_reservations(id),\n    launch_run_id TEXT NOT NULL UNIQUE\n)',
    "CREATE TABLE automatic_wake_attempts (\n    id TEXT PRIMARY KEY,\n    chain_id TEXT NOT NULL REFERENCES automatic_work_chains(id),\n    conversation_id TEXT NOT NULL,\n    session_id TEXT NOT NULL,\n    owner_id TEXT NOT NULL,\n    generation_reservation_id TEXT NOT NULL UNIQUE REFERENCES automatic_work_reservations(id),\n    run_ids_json TEXT NOT NULL,\n    cause TEXT NOT NULL DEFAULT 'completion' CHECK (cause IN ('completion', 'progress', 'mixed')),\n    message_ids_json TEXT NOT NULL DEFAULT '[]',\n    state TEXT NOT NULL CHECK (state IN ('prepared', 'accepted', 'completed', 'aborted', 'review_required')),\n    created_at REAL NOT NULL,\n    accepted_at REAL,\n    completed_at REAL\n, attempt_kind TEXT NOT NULL DEFAULT 'fleet_wake' CHECK (attempt_kind IN ('fleet_wake', 'goal_iteration', 'workflow_phase')))",
